/**
 * Optional Three.js renderer for the office scene.
 *
 * This is deliberately an adapter, not a second world model: callers still
 * provide the same Part[] generated by officeWorld and keep all navigation,
 * seating and behaviour contracts in the existing renderer.  If Three or a
 * WebGL context is unavailable the caller can continue using OfficeRenderer.
 */
import {THREE,GLTFLoader,RGBELoader} from './realisticRuntime';
import type {Part,RenderQuality} from './officeRenderer';
import {officeOverview,officeProjection} from './officeCamera';
import {lookAt} from './scene';
import {modelMeshes,bevelBox} from './visualMeshes';
