 private sync(parts:Part[],group:AnyObject,pools:Map<string,AnyObject>){const buckets=new Map<string,Part[]>();for(const p of parts){if(p.surface==='shadow')continue;const key=`${p.mesh||'cube'}|${p.surface||'matte'}|${p.alpha??1}|${p.roughness??''}|${p.metalness??''}|${p.emissive??0}|${p.nightEmissive??0}|${p.castShadow!==false}|${p.color.join(',')}`;(buckets.get(key)||buckets.set(key,[]).get(key)!).push(p);}for(const [key,list]of buckets){let pool=pools.get(key);if(!pool||pool.capacity<list.length){if(pool){group.remove(pool.mesh);pool.mesh.dispose();}const proto=list[0],mesh=new THREE.InstancedMesh(this.geometry(proto),this.material(proto),Math.max(8,list.length));mesh.castShadow=proto.castShadow!==false;mesh.receiveShadow=true;mesh.frustumCulled=false;pool={mesh,capacity:Math.max(8,list.length)};pools.set(key,pool);group.add(mesh);}pool.mesh.material=this.material(list[0]);pool.mesh.count=list.length;for(let i=0;i<list.length;i++){pool.mesh.setMatrixAt(i,this.matrix(list[i]));pool.mesh.setColorAt(i,new THREE.Color(...list[i].color).convertSRGBToLinear());}pool.mesh.instanceMatrix.needsUpdate=true;pool.mesh.instanceColor.needsUpdate=true;pool.mesh.userData={tag:list[0].tag,zoneId:(list[0] as AnyObject).zoneId};}for(const [key,pool]of pools)if(!buckets.has(key)){group.remove(pool.mesh);pool.mesh.dispose();pools.delete(key);}}
 setStatic(parts:Part[]){if(this.disposed)return;this.staticParts=parts;this.sync(parts,this.staticGroup,this.staticPools);this.stats.staticTriangles=parts.reduce((n,p)=>n+(this.geometry(p).attributes.position.count/3),0);}
